package net.officefloor.hq.app.voidreason;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** The reason is already on the sheet's list of void reasons. */
@ResponseStatus(HttpStatus.CONFLICT)
public class DuplicateVoidReasonException extends RuntimeException {}
package net.officefloor.hq.app.voidreason;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** A void reason cannot be blank. */
@ResponseStatus(HttpStatus.BAD_REQUEST)
public class VoidReasonBlankException extends RuntimeException {}
package net.officefloor.hq.app.voidreason;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/void-reasons")
public class VoidReasonController {

    /** A void reason on the sheet. */
    public record VoidReasonView(Long id, String reason) {
        static VoidReasonView of(VoidReason r) {
            return new VoidReasonView(r.getId(), r.getReason());
        }
    }

    /** A void reason's text. */
    public record VoidReasonRequest(@NotBlank @Size(max = 200) String reason) {}

    private final VoidReasonService service;

    public VoidReasonController(VoidReasonService service) {
        this.service = service;
    }

    @GetMapping
    public List<VoidReasonView> list(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return service.reasons(sheetId).stream().map(VoidReasonView::of).toList();
    }

    @PostMapping
    public VoidReasonView add(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid VoidReasonRequest request) {
        return VoidReasonView.of(service.add(sheetId, user, request.reason()));
    }
}
package net.officefloor.hq.app.voidreason;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/** A reason a claim of the sheet may be voided with, each at most once. */
@Entity
@Table(name = "void_reason")
public class VoidReason {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "reason", nullable = false, length = 200)
    private String reason;

    protected VoidReason() {}

    public VoidReason(String sheetId, String reason) {
        this.sheetId = sheetId;
        this.reason = reason;
    }

    public Long getId() { return id; }

    public String getSheetId() { return sheetId; }

    public String getReason() { return reason; }
}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;

public interface VoidReasonRepository extends JpaRepository<VoidReason, Long> {

    List<VoidReason> findBySheetIdOrderByIdAsc(String sheetId);

    boolean existsBySheetId(String sheetId);

    boolean existsBySheetIdAndReason(String sheetId, String reason);
}
package net.officefloor.hq.app.voidreason;

import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.ResponseStatus;

/** While the sheet's list of void reasons is not empty, a claim is voided only with a reason on it. */
@ResponseStatus(HttpStatus.UNPROCESSABLE_CONTENT)
public class VoidReasonRequiredException extends RuntimeException {}
package net.officefloor.hq.app.voidreason;

import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * A sheet's list of void reasons, each at most once. While the list is not empty, a claim is voided
 * only with a reason chosen from it.
 */
@Service
public class VoidReasonService {

    private final SheetRepository sheets;
    private final VoidReasonRepository reasons;
    private final Audit audit;

    public VoidReasonService(SheetRepository sheets, VoidReasonRepository reasons, Audit audit) {
        this.sheets = sheets;
        this.reasons = reasons;
        this.audit = audit;
    }

    /** The sheet's void reasons, in the order they were added. */
    @Transactional(readOnly = true)
    public List<VoidReason> reasons(String sheetId) {
        return reasons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a reason, trimmed with its inner spaces collapsed; refused when blank or already on the list. */
    @Transactional
    public VoidReason add(String sheetId, String user, String reason) {
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        String text = textOf(reason);
        if (text == null) throw new VoidReasonBlankException();
        if (reasons.existsBySheetIdAndReason(sheetId, text)) throw new DuplicateVoidReasonException();
        VoidReason saved = reasons.saveAndFlush(new VoidReason(sheetId, text));
        audit.recordOnCommit("VOID_REASON_ADDED sheet=" + sheetId + " by=" + user.strip() + " reason=" + text);
        return saved;
    }

    /**
     * The reason a claim is voided with: none while the sheet's list is empty, else the given one,
     * which must be on the list.
     */
    @Transactional(readOnly = true)
    public String reasonForVoid(String sheetId, String reason) {
        if (!reasons.existsBySheetId(sheetId)) return null;
        String text = textOf(reason);
        if (text == null || !reasons.existsBySheetIdAndReason(sheetId, text)) throw new VoidReasonRequiredException();
        return text;
    }

    /** The reason trimmed, inner spaces collapsed; null when blank. */
    private static String textOf(String reason) {
        if (reason == null) return null;
        String text = reason.strip().replaceAll("\\s+", " ");
        return text.isEmpty() ? null : text;
    }
}
package net.officefloor.hq.app.quickadd;

import jakarta.validation.Valid;
