@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}")
public class QuickAddController {

    /** The person the claim went to, whether they were added for it, and the claim. */
    public record QuickAddView(PersonView person, boolean added, ClaimView claim) {}

    /** A person's name, as the person form takes it, and a claim's amount, as the claim form takes it. */
    public record QuickAddRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "\\d{1,12}(\\.\\d{1,2})?") String amount) {

        BigDecimal amountValue() {
            return new BigDecimal(amount).setScale(2);
        }
    }

    private final QuickAddService service;
    private final PersonService people;

    public QuickAddController(QuickAddService service, PersonService people) {
        this.service = service;
        this.people = people;
    }

    @PostMapping("/quick-add")
    public QuickAddView add(
            @PathVariable @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Valid QuickAddRequest request) {
        QuickAddService.QuickAdded done = service.add(sheetId, user, request.name().strip(), request.amountValue());
        return new QuickAddView(PersonView.of(done.person(), people.today(done.person().getSheetId()), people.patronIdsOf(done.person().getId()),
                people.watches(done.person().getId(), user), people.isActive(done.person())), done.added(), ClaimView.of(done.claim()));
    }
}
package net.officefloor.hq.app.quickadd;

import java.math.BigDecimal;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Quick-add: a DRAFT claim of an amount, dated the entry date while set (else the sheet's today) with an empty note, for the person
 * of a name or alias (ignoring case and surrounding spaces); with no such person on the sheet, they are added
 * first with grade A. It is one change: a refused claim rolls back the person added for it too.
 */
@Service
public class QuickAddService {

    static final String GRADE = "A";

    /** The person the claim went to, whether they were added for it, and the claim. */
    public record QuickAdded(Person person, boolean added, Claim claim) {}

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    @Transactional
    public QuickAdded add(String sheetId, String user, String name, BigDecimal amount) {
        Person existing = people.findByNameOrAlias(sheetId, name).orElse(null);
        Person person = existing != null ? existing : personService.add(sheetId, user, name, GRADE);
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "", null);
        return new QuickAdded(person, existing == null, claim);
    }
}
