418	  /** The person's grace days for a claim dated on a date, of the grade they had then. */
419	  readonly graceOn = input.required<GraceOn>();
420	  /** The sheet's periods, for the one each claim's due-by falls in. */
421	  readonly periods = input.required<Period[]>();
422	  /** A claim added, edited or given a new status, as the store now holds it. */
423	  readonly saved = output<Claim>();
424	  /** The other people on the sheet a claim may be moved to. */
425	  readonly others = input.required<{ id: number; name: string }[]>();
426	  /** A claim moved to another person, as the store now holds it. */
427	  readonly moved = output<Claim>();
428	  /** The ids of the claims selected for a bulk change. */
429	  readonly selected = input.required<ReadonlySet<number>>();
430	  /** A claim's checkbox ticked or cleared. */
431	  readonly toggled = output<{ id: number; checked: boolean }>();
432	
433	  protected readonly na = NA;
434	  protected readonly editingId = signal<number | null>(null);
435	  /** A submit is under way; another one waits for its answer rather than storing twice. */
436	  private saving = false;
437	  /** The lock the editor last opened is taking; a save of it waits for it, and is dropped if it was refused. */
438	  private locking: Promise<boolean> = Promise.resolve(true);
439	  protected readonly error = signal('');
440	  /** The error from the last action on a claim's row, if it was refused. */
441	  protected readonly claimError = signal<{ id: number; message: string } | null>(null);
442	  protected readonly form = new FormGroup({
443	    amount: new FormControl('', { nonNullable: true }),
444	    date: new FormControl('', { nonNullable: true }),
445	    note: new FormControl('', { nonNullable: true }),
