451	  constructor() {
452	    this.form.valueChanges.subscribe(() => this.error.set(''));
453	    // An editor this user left open (its lock survives a re-load of the sheet) opens again.
454	    effect(() => {
455	      const claims = this.claims();
456	      untracked(() => {
457	        if (this.editingId() !== null) return;
458	        const user = this.session.user();
459	        const mine = claims.find((c) => c.status === 'DRAFT' && user !== null && c.lockedBy === user);
460	        if (mine) this.openEditor(mine);
461	      });
462	    });
463	  }
