469	  /** The due fixed when it was settled, else its figure with its late charge on top. */
470	  protected dueOf(c: Claim): string {
471	    const due = claimDueCents(c, this.pctOn(), this.session.floorCentsOn, this.session.late(), roundsOn(c, this.claims()), this.graceOn());
472	    return due === null ? NA : money(due);
473	  }
474	
475	  protected overdueOf(c: Claim): boolean {
476	    return isOverdue(c, this.session.today(), this.graceOn());
477	  }
478	
479	  /**
480	   * Shown as deferred while its deferred-until date is after the sheet's today, whatever its status since
481	   * (a deferred claim voided stays marked); only an OPEN one is kept out of the totals ({@link isDeferred}).
482	   */
483	  protected deferredOf(c: Claim): boolean {
484	    const today = this.session.today();
485	    return c.deferredUntil !== null && today !== null && today < c.deferredUntil;
486	  }
487	
488	  /** The name of the period its due-by falls in, or blank when none. */
489	  protected periodOf(c: Claim): string {
490	    return periodOn(this.periods(), c.dueBy)?.name ?? '';
