503	  private openEditor(c: Claim): void {
504	    this.editingId.set(c.id);
505	    this.form.setValue({ amount: c.amount, date: c.date, note: c.note, corrects: c.corrects ?? '',
506	      ref: c.ref ?? '', tags: c.tags.join(', ') },
507	      { emitEvent: false });
