511	  /**
512	   * Open a claim's editor, locking the claim for every other user until it is saved or cancelled; a claim
513	   * that cannot be edited, one another user's editor locks, or a user whose role may change nothing is refused.
514	   */
515	  protected async edit(c: Claim): Promise<void> {
516	    this.claimError.set(null);
517	    if (closedOn(this.periods(), c.dueBy)) {
518	      this.claimError.set({ id: c.id, message: CLOSED });
519	      return;
520	    }
521	    if (c.status !== 'DRAFT') {
522	      this.claimError.set({ id: c.id, message: notEditable(c.status) });
523	      return;
524	    }
525	    const sheet = this.session.sheetId();
526	    if (!sheet) return;
527	    const open = this.editingId();
528	    // The editor opens at once with the claim as shown, so what is typed while the lock is taken is
529	    // kept; a save waits for the lock, and a refused lock closes the editor again.
530	    this.openEditor(c);
531	    const locking = this.lock(sheet, c, open);
532	    this.locking = locking;
533	    await locking;
534	  }
