536	  /** Take the lock of the claim whose editor has opened, after releasing the one left open; whether it was taken. */
537	  private async lock(sheet: string, c: Claim, open: number | null): Promise<boolean> {
538	    if (open !== null && open !== c.id) await this.release(sheet, open);
539	    const url = `/api/sheets/${encodeURIComponent(sheet)}/claims/${c.id}/edit`;
540	    try {
541	      const claim = await firstValueFrom(this.http.post<Claim>(url, null, { headers: this.headers() }));
542	      if (this.session.sheetId() !== sheet) return false;
543	      this.saved.emit(claim);
544	      return true;
545	    } catch (e) {
546	      if (this.session.sheetId() !== sheet) return false;
547	      if (this.editingId() === c.id) this.reset();
548	      const message = e instanceof HttpErrorResponse && e.status === 423
549	        ? CLOSED
550	        : e instanceof HttpErrorResponse && e.status === 409
551	        ? notEditable(undefined)
552	        : e instanceof HttpErrorResponse && e.status === 412
